// ============================================================================
//  The host capability manifest (WIRE_FORMAT.md §27) and the corpus-family gate
//  (§27.7, Phase 1938).
//
//  The manifest is generated by scripts/host-capability.mjs; this test runs its
//  --check, so the gate and the CLI share one implementation. The family gate
//  derives the family set from the corpus tree and fails on a family the
//  manifest does not name, or one it names that the corpus no longer has.
//
//  The token claim (Phase 2332) is read back against the corpus: every fixture
//  of the round-trip families is walked against the corpus's idl.json for the
//  construct tokens it exercises (§27.4). A token the corpus exercises and this
//  host does not claim fails by name; so does a claimed token carried by a
//  fixture this host does not round-trip.
// ============================================================================

import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import { decodeNode, decodeOp, encodeNode, encodeOp } from '@fuaran-ui/ops';

import { wireCorpusRoot } from '../../../dev-scripts/corpus-root.mjs';
import {
  constructTokens,
  corpusFamilies,
  DERIVED_FAMILIES,
  HOST_CORPUS_FAMILIES,
  manifestPath,
  tokenFamily,
  TYPE_MODEL,
} from '../scripts/host-capability.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = join(here, '..');
const script = join(packageRoot, 'scripts', 'host-capability.mjs');

describe('host capability manifest', () => {
  it('is what this host declares (re-run scripts/host-capability.mjs on mismatch)', () => {
    const result = spawnSync(process.execPath, [script, '--check'], {
      encoding: 'utf8',
      cwd: packageRoot,
    });
    const report = (result.stderr || result.stdout || '').trim();
    expect(result.status, `host-capability --check said:\n${report}`).toBe(0);
  });

  it('names every corpus family and no other', () => {
    // The corpus is the oracle: an absent one throws in the resolver or fails
    // the read below, never skips.
    const families = corpusFamilies(wireCorpusRoot());
    const declared = new Set(Object.keys(HOST_CORPUS_FAMILIES));
    const missing = [...families].filter((f) => !declared.has(f)).sort();
    const stale = [...declared].filter((f) => !families.has(f)).sort();
    expect(missing, 'corpus families this host does not name').toEqual([]);
    expect(stale, 'families this host names that the corpus no longer has').toEqual([]);
  });

  it('derives a self-enumerated family the printer could not see', () => {
    const dir = mkdtempSync(join(tmpdir(), 'fuaran-ts-families-'));
    try {
      const write = (rel: string, body: string) => {
        mkdirSync(dirname(join(dir, rel)), { recursive: true });
        writeFileSync(join(dir, rel), body);
      };
      write('manifest.json', '{"fixtures":[{"kind":"node-round-trip"}]}');
      write('newfamily/manifest.json', '{"cases":[]}');
      write('split/manifest.json', '{"families":[{"id":"a"},{"id":"b"}]}');
      write('goldens/goldens.json', '{}');
      expect([...corpusFamilies(dir)].sort()).toEqual([
        'newfamily',
        'node-round-trip',
        'split/a',
        'split/b',
      ]);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

// ─── The token claim (§27.1–27.4, Phase 2332) ────────────────────────────────

const published = (): { tokens: string[]; families: Record<string, { covered: boolean }> } =>
  JSON.parse(readFileSync(manifestPath, 'utf8'));

describe('host capability token claim', () => {
  const baseline = new Set(constructTokens(TYPE_MODEL));

  it('claims tokens only in the derived families, and covers exactly those', () => {
    const doc = published();
    const covered = Object.keys(doc.families).filter((f) => doc.families[f]?.covered);
    expect(covered.sort()).toEqual([...DERIVED_FAMILIES].sort());
    const outside = doc.tokens.filter((t) => !DERIVED_FAMILIES.includes(tokenFamily(t)));
    expect(outside, 'tokens outside the covered families').toEqual([]);
  });

  it('removing a kind from the model removes exactly that kind and its members', () => {
    const { Badge: _gone, ...kindFields } = TYPE_MODEL.kindFields;
    const model = {
      ...TYPE_MODEL,
      kinds: TYPE_MODEL.kinds.filter((k) => k !== 'Badge'),
      kindFields,
    };
    const after = new Set(constructTokens(model));
    expect([...baseline].filter((t) => !after.has(t))).toEqual([
      'Kind.Badge',
      'Kind.Badge.label',
      'Kind.Badge.variant',
    ]);
  });

  it('removing a union case removes exactly that case and its members', () => {
    const { Static: _gone, ...binding } = TYPE_MODEL.unionCases['Binding'] ?? {};
    const model = { ...TYPE_MODEL, unionCases: { ...TYPE_MODEL.unionCases, Binding: binding } };
    const after = new Set(constructTokens(model));
    expect([...baseline].filter((t) => !after.has(t))).toEqual([
      'Binding.Static',
      'Binding.Static.value',
    ]);
  });

  it('a hostOnly row is no token: it never reaches the wire', () => {
    expect(baseline.has('Action.Dispatch')).toBe(true);
    expect(baseline.has('Action.Dispatch.msg')).toBe(false);
  });

  it('every token the corpus exercises is claimed, and every claimed one round-trips', () => {
    const byToken = exercising(wireCorpusRoot());
    // The walk reaches every derived family, or the check below reads nothing there.
    const reached = new Set([...byToken.keys()].map(tokenFamily));
    expect([...reached].sort()).toEqual([...DERIVED_FAMILIES].sort());
    const findings = claimFindings(published().tokens, byToken, roundTrips);
    expect(findings, 'the claim and the corpus disagree').toEqual([]);
  });

  it('falsifier: a token the corpus exercises and the claim omits fails by name', () => {
    const claim = [...baseline].filter((t) => t !== 'Kind.Badge');
    const findings = claimFindings(claim, exercising(wireCorpusRoot()), roundTrips);
    expect(findings).toHaveLength(1);
    expect(findings[0]).toMatch(/^Kind\.Badge: the corpus exercises it \(/);
  });

  it('falsifier: a claimed token in a fixture this host does not round-trip fails by name', () => {
    const byToken = exercising(wireCorpusRoot());
    const victim = byToken.get('Kind.Badge')?.[0]?.id ?? '';
    expect(victim, 'a fixture exercising Kind.Badge').not.toBe('');
    const findings = claimFindings([...baseline], byToken, (f) => f.id !== victim);
    expect(findings.length).toBeGreaterThan(0);
    expect(findings.every((f) => f.includes(victim))).toBe(true);
    expect(findings.some((f) => f.startsWith('Kind.Badge: claimed'))).toBe(true);
  });
});

// The corpus vocabulary is read from the corpus's own idl.json — never from this
// host's tables — so the claim is checked against the oracle, not against itself.

interface IdlTy {
  readonly $type: string;
  readonly name?: string;
  readonly args?: readonly IdlTy[];
  readonly of?: IdlTy;
  readonly items?: readonly IdlTy[];
  readonly values?: IdlTy;
  readonly wire?: unknown;
}
interface IdlField {
  readonly name: string;
  readonly type: IdlTy;
}
interface Idl {
  readonly kinds: readonly { readonly tag: string; readonly fields?: readonly IdlField[] }[];
  readonly unions: readonly {
    readonly name: string;
    readonly cases: readonly { readonly tag: string; readonly fields?: readonly IdlField[] }[];
  }[];
  readonly records: readonly { readonly name: string; readonly fields: readonly IdlField[] }[];
  readonly ops: readonly { readonly tag: string; readonly fields?: readonly IdlField[] }[];
  readonly nodeFields: readonly IdlField[];
  readonly harden: {
    readonly transparentUnions: readonly { readonly union: string; readonly case: string }[];
  };
}

interface Fixture {
  readonly id: string;
  readonly kind: string;
  readonly decoder: string;
  readonly expectedFile: string;
}

/** The families whose canonical documents are wire trees a host decodes and re-encodes. */
const EXERCISING_FAMILIES = ['node-round-trip', 'op-round-trip', 'lenient-accept'];

const isObject = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

/** A wire object's `$type` discriminator, if it carries one. */
const discriminator = (v: unknown): string | undefined => {
  const tag = isObject(v) ? v['$type'] : undefined;
  return typeof tag === 'string' ? tag : undefined;
};

/** The tokens one wire value exercises, walked against the corpus IDL (§27.4). */
const walker = (idl: Idl) => {
  const kinds = new Map(idl.kinds.map((k) => [k.tag, k.fields ?? []]));
  const ops = new Map(idl.ops.map((o) => [o.tag, o.fields ?? []]));
  const unions = new Map(
    idl.unions.map((u) => [u.name, new Map(u.cases.map((c) => [c.tag, c.fields ?? []]))]),
  );
  const records = new Map(idl.records.map((r) => [r.name, r.fields]));
  const transparent = new Map(idl.harden.transparentUnions.map((t) => [t.union, t.case]));
  const bind = (t: IdlTy, arg: IdlTy | undefined): IdlTy => (t.$type === 'var' && arg ? arg : t);
  const members = (
    v: unknown,
    fields: readonly IdlField[],
    owner: string | null,
    arg: IdlTy | undefined,
    out: Set<string>,
  ): void => {
    if (!isObject(v)) return;
    for (const f of fields) {
      if (!(f.name in v)) continue;
      if (owner !== null) out.add(`${owner}.${f.name}`);
      walk(v[f.name], bind(f.type, arg), out);
    }
  };
  const walk = (v: unknown, t: IdlTy, out: Set<string>): void => {
    switch (t.$type) {
      case 'node':
        if (!isObject(v)) return;
        walk(v['kind'], { $type: 'kind' }, out);
        members(v, idl.nodeFields, null, undefined, out);
        return;
      case 'kind': {
        const tag = discriminator(v);
        if (tag === undefined) return;
        out.add(`Kind.${tag}`);
        members(v, kinds.get(tag) ?? [], `Kind.${tag}`, undefined, out);
        return;
      }
      case 'op': {
        const tag = discriminator(v);
        if (tag !== undefined) members(v, ops.get(tag) ?? [], null, undefined, out);
        return;
      }
      case 'union': {
        const name = t.name ?? '';
        const tag = discriminator(v);
        if (tag !== undefined) {
          out.add(`${name}.${tag}`);
          members(v, unions.get(name)?.get(tag) ?? [], `${name}.${tag}`, t.args?.[0], out);
        } else if (transparent.has(name)) {
          out.add(`${name}.${transparent.get(name)}`);
        }
        return;
      }
      case 'record':
        members(v, records.get(t.name ?? '') ?? [], t.name ?? '', undefined, out);
        return;
      case 'hosted':
        // A hosted slot whose wire type the IDL declares is walked through it;
        // one carried as bare JSON is opaque here, as it is to the IDL (§27.5).
        if (isObject(t.wire)) walk(v, t.wire as unknown as IdlTy, out);
        return;
      case 'list':
        if (!Array.isArray(v)) return;
        v.forEach((item, i) => {
          const of = t.of ?? t.items?.[i];
          if (of) walk(item, of, out);
        });
        return;
      case 'map':
        if (isObject(v) && t.values) {
          for (const item of Object.values(v)) walk(item, t.values, out);
        }
        return;
      default:
        return;
    }
  };
  return walk;
};

/** Each token the corpus exercises, with the round-trip fixtures that carry it. */
const exercising = (root: string): Map<string, Fixture[]> => {
  const idl = JSON.parse(readFileSync(join(root, 'idl.json'), 'utf8')) as Idl;
  const walk = walker(idl);
  const manifest = JSON.parse(readFileSync(join(root, 'manifest.json'), 'utf8')) as {
    readonly fixtures: readonly Fixture[];
  };
  const byToken = new Map<string, Fixture[]>();
  for (const f of manifest.fixtures) {
    if (!EXERCISING_FAMILIES.includes(f.kind)) continue;
    const found = new Set<string>();
    const doc: unknown = JSON.parse(readFileSync(join(root, f.expectedFile), 'utf8'));
    walk(doc, { $type: f.decoder }, found);
    for (const token of found) byToken.set(token, [...(byToken.get(token) ?? []), f]);
  }
  return byToken;
};

/** This host round-trips a fixture's canonical document byte-identically. */
const roundTrips = (f: Fixture): boolean => {
  const expected = readFileSync(join(wireCorpusRoot(), f.expectedFile), 'utf8').replace(/\n$/, '');
  if (f.decoder === 'op') {
    const d = decodeOp(expected);
    return d.ok && encodeOp(d.value) === expected;
  }
  const d = decodeNode(expected);
  return d.ok && encodeNode(d.value) === expected;
};

/** Every way the claim and the corpus disagree, one finding per token. */
const claimFindings = (
  claim: readonly string[],
  byToken: ReadonlyMap<string, readonly Fixture[]>,
  run: (f: Fixture) => boolean,
): string[] => {
  const claimed = new Set(claim);
  const verdicts = new Map<string, boolean>();
  const green = (f: Fixture): boolean => {
    const known = verdicts.get(f.id);
    if (known !== undefined) return known;
    const verdict = run(f);
    verdicts.set(f.id, verdict);
    return verdict;
  };
  const findings: string[] = [];
  for (const token of [...byToken.keys()].sort()) {
    const fixtures = byToken.get(token) ?? [];
    if (!claimed.has(token)) {
      findings.push(
        `${token}: the corpus exercises it (${fixtures[0]?.id}) and this host does not claim it`,
      );
      continue;
    }
    const red = fixtures.filter((f) => !green(f)).map((f) => f.id);
    if (red.length > 0) {
      findings.push(`${token}: claimed, and this host does not round-trip ${red.join(', ')}`);
    }
  }
  return findings;
};
